function centroid(points) {
  let x = 0;
  let y = 0;
  for (const [px, py] of points) {
    x += px;
    y += py;
  }
  return [x / points.length, y / points.length];
}

function eyePath(eyes, index) {
  const points = OUTLINE[index];
  const [cx, cy] = centroid(points);
  const tilt = (35 * Math.PI) / 180;
  const turn = (eyes.ang[index] * Math.PI) / 180;
  const [sx, sy] = eyes.seat[index];
  const cosT = Math.cos(tilt);
  const sinT = Math.sin(tilt);
  const cosA = Math.cos(turn);
  const sinA = Math.sin(turn);
  const width = eyes.w[index];
  const length = eyes.l[index];
  const placed = points.map(([px, py]) => {
    const dx = px - cx;
    const dy = py - cy;
    const localX = (dx * cosT - dy * sinT) * width;
    const localY = (dx * sinT + dy * cosT) * length;
    return [
      sx + localX * cosA - localY * sinA,
      sy + localX * sinA + localY * cosA,
    ];
  });
  return `M${placed.map(([x, y]) => `${x.toFixed(2)} ${y.toFixed(2)}`).join("L")}Z`;
}

export function markEyes(shape) {
  const eyes = MARKS[shape].eyes;
  return [eyePath(eyes, 0), eyePath(eyes, 1)];
}

const hulls = new Map();

function cross(o, a, b) {
  return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
}

function convexHull(points) {
  const sorted = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const half = (list) => {
    const chain = [];
    for (const point of list) {
      while (chain.length >= 2) {
        const a = chain[chain.length - 2];
        const b = chain[chain.length - 1];
        if (!a || !b || cross(a, b, point) > 0) break;
        chain.pop();
      }
      chain.push(point);
    }
    chain.pop();
    return chain;
  };
  return [...half(sorted), ...half(sorted.reverse())];
}

// Visvalingam: drop the vertex that adds the least area until few enough remain,
// so the tips of stars and sparkles survive while flat runs collapse.
function simplify(hull, limit) {
  const points = [...hull];
  while (points.length > limit) {
    let weakest = 0;
    let least = Number.POSITIVE_INFINITY;
    points.forEach((point, index) => {
      const before = points[(index - 1 + points.length) % points.length];
      const after = points[(index + 1) % points.length];
      if (!before || !after) return;
      const area = Math.abs(cross(before, point, after));
      if (area < least) {
        least = area;
        weakest = index;
      }
    });
    points.splice(weakest, 1);
  }
  return points;
}

/** Convex outline of a mark in viewBox units, for collision bodies. */
export function markHull(shape, limit = 20) {
  const cached = hulls.get(shape);
  if (cached) return cached;
  const values = MARKS[shape].path.match(/-?\d+(?:\.\d+)?/g)?.map(Number) ?? [];
  const points = [];
  for (let i = 0; i + 1 < values.length; i += 2) {
    const x = values[i];
    const y = values[i + 1];
    if (x !== undefined && y !== undefined) points.push([x, y]);
  }
  const hull = simplify(convexHull(points), limit);
  hulls.set(shape, hull);
  return hull;
}

export function markViewBox() {
  const size = MARK_RADIUS * 2;
  const origin = MARK_CENTER - MARK_RADIUS;
  return `${origin.toFixed(2)} ${origin.toFixed(2)} ${size.toFixed(2)} ${size.toFixed(2)}`;
}
